<template><main class="page"><section class="hero"><div class="wrap"><NuxtLink to="/spec-library" class="back">← Spec Library</NuxtLink><div class="kicker">BROWSE HISTORICAL SPECIFICATIONS</div><h1>Manufacturers</h1><p>Select a manufacturer to browse its historical machines organized by machine type and model.</p></div></section><section class="wrap section"><div class="grid"><NuxtLink v-for="m in manufacturers" :key="m" :to="'/spec-library/manufacturers/'+slug(m)" class="card">{{m}}</NuxtLink></div></section></main></template><script setup>
import historicalMachines from '~/assets/data/historical-machines.json'
const clean=s=>String(s||'').trim()
const slug=s=>clean(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')
const rows=historicalMachines.filter(m=>clean(m.Manufacturer)&&clean(m.Model)&&clean(m.WebDesc||m.Web_Desc))
const manufacturers=[...new Set(rows.map(m=>clean(m.Manufacturer)))].sort((a,b)=>a.localeCompare(b))
useSeoMeta({title:'Machine Manufacturers | UMS Spec Library',description:'Browse historical machinery specifications by manufacturer in the Used Machinery Source Spec Library.'})
</script><style scoped>.page{color:#17273a;padding-bottom:60px}.wrap{max-width:1200px;margin:auto;padding:0 28px}.hero{background:#0b2545;color:#fff;padding:46px 0;border-bottom:4px solid #f47b20}.back{color:#c8d9eb}.kicker{color:#f47b20;font-size:.78rem;font-weight:900;letter-spacing:.12em;margin:16px 0 8px}.hero h1{font-size:3rem;margin:0 0 10px}.section{padding-top:38px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card{padding:14px;border:1px solid #d7e0e8;border-radius:7px;color:#0b2545;font-weight:800;text-decoration:none}.card:hover{border-color:#f47b20}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.wrap{padding:0 18px}}</style>